contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public function containing the test
    // params:
    // - jojoTeamAddr: address to set as jojoTeam in C (must be done off-chain before calling test)
    // - caller: address that will be used as msg.sender when calling newEmergencyOracle (simulated by passing as parameter to determine expectation)
    // - description: string passed through to newEmergencyOracle
    // The function will attempt to call newEmergencyOracle via c and then assert that only when caller == address(this) (i.e., msg.sender) the call can succeed.
    // Since we cannot change msg.sender in Solidity, we observe behavior via two calls: one performed directly (msg.sender = this contract)
    // and one attempted by expecting that an externally-originated caller (tx.origin != msg.sender) would fail under P.

    // Note: The test relies on C.newEmergencyOracle reverting for non-jojoTeam callers under the original contract P
    // and on the mutant M allowing a tx.origin-based caller to succeed when tx.origin == jojoTeam even if msg.sender != jojoTeam.

    function runTest(address jojoTeamAddr, address caller, string calldata description) external {
        // Precondition: caller must not be address(0)
        require(caller != address(0), "caller cannot be zero");

        // Attempt 1: call newEmergencyOracle directly from this contract (msg.sender == address(this)).
        // This represents a legitimate call when jojoTeam is set to this contract's address.
        bool successDirect;
        try c.newEmergencyOracle(description) {
            successDirect = true;
        } catch {
            successDirect = false;
        }

        // Attempt 2: we cannot change msg.sender here, but we can observe the permission outcome that depends on whether
        // C thinks the caller is the jojoTeam. Under P the check is msg.sender == jojoTeam, so the only way a different
        // externally-originated EOA (where tx.origin==caller but msg.sender==some intermediary) could pass is if
        // tx.origin is compared. The mutant M compares tx.origin, allowing calls where tx.origin==jojoTeam even if
        // msg.sender != jojoTeam. We model this by observing that when this contract is not jojoTeam and the provided
        // 'caller' is equal to jojoTeamAddr, then under P a call from this contract should NOT succeed, but under M
        // a transaction with tx.origin==caller might succeed. Since we cannot actually originate the tx from 'caller',
        // we encode the distinguishing property as an assertion about observed direct-call success vs the relation
        // between 'caller' and 'jojoTeamAddr'.

        // The distinguishing general rule to assert:
        // If this contract is NOT the jojoTeam (i.e., address(this) != jojoTeamAddr), then calling newEmergencyOracle
        // directly from this contract must revert (successDirect == false). The mutant that checks tx.origin would
        // allow a call when tx.origin == jojoTeamAddr even though msg.sender != jojoTeamAddr, so the rule is violated by M.

        assert((address(this) != jojoTeamAddr) ? (successDirect == false) : true);
    }

    // fallback/receive not used but allowed
    receive() external payable {}
}

